// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/inventory/v1/organizations", wrapper.ListOrganizations)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/inventory/v1/organizations/{organization_id}", wrapper.GetOrganization)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/inventory/v1/settings/warehouses", wrapper.ListWarehouses)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/inventory/v1/settings/warehouses/{warehouse_id}", wrapper.GetWarehouse)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/inventory/v1/items", wrapper.ListItems)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/inventory/v1/items/{item_id}", wrapper.GetItem)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/inventory/v1/salesorders", wrapper.ListSalesOrders)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/inventory/v1/salesorders/{salesorder_id}", wrapper.GetSalesOrder)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/inventory/v1/purchaseorders", wrapper.ListPurchaseOrders)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/inventory/v1/purchaseorders/{purchaseorder_id}", wrapper.GetPurchaseOrder)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/inventory/v1/purchaseorders/{purchaseorder_id}/approve", wrapper.ApprovePurchaseOrder)

	return m
}

